import { VerificationState } from "@unomed/react-native-matrix-sdk";
import { useAtomValue, useSetAtom } from "jotai";
import { NavigationContainerRef } from "modules/navigation/const";
import { VerificationService } from "modules/verification/service/VerificationService";
import { type FC, useEffect } from "react";
import Toast from "react-native-toast-message";
import { offlineToastHelper } from "shared/utils";
import { MatrixAtoms } from "../jotai";

const VERIFICATION_SCREENS: (keyof Routes)[] = [
  "splash",
  "confirmIdentity",
  "cantConfirm",
  "oidcResetWebView",
  "verifyWithDevice",
  "enterRecoveryKey",
  "setUpRecoveryKey",
];

export const VerificationProvider: FC = () => {
  const client = useAtomValue(MatrixAtoms.matrixClient);
  const syncService = useAtomValue(MatrixAtoms.syncService);
  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
  const setVerificationEmojis = useSetAtom(MatrixAtoms.verificationEmojis);
  const setVerificationSenderName = useSetAtom(
    MatrixAtoms.verificationSenderName,
  );

  useEffect(() => {
    if (!client || !syncService) return;

    let cancelled = false;

    const setup = async () => {
      try {
        await VerificationService.setupVerification(
          // On verification request received
          (details) => {
            const senderName =
              details.senderProfile.displayName || details.senderProfile.userId;
            setVerificationSenderName(senderName);
            setVerificationStatus("incomingRequest");
            NavigationContainerRef.navigate("verifyUser", {
              userId: details.senderProfile.userId,
              flowId: details.flowId,
            });
          },
          // On emojis received
          (emojis) => {
            setVerificationEmojis(emojis);
            setVerificationStatus("emojis");
          },
          // On state change
          (state) => {
            console.log("Verification state changed:", state);

            if (state === "success") {
              setVerificationStatus("success");
              setVerificationEmojis(null);
              setVerificationSenderName(null);
              Toast.show({
                type: "success",
                text1: "Device verified successfully!",
              });
            } else if (state === "failed") {
              setVerificationStatus("failed");
              setVerificationEmojis(null);
              setVerificationSenderName(null);
              offlineToastHelper("Verification failed");
            } else if (state === "cancelled") {
              setVerificationStatus("cancelled");
              setVerificationEmojis(null);
              setVerificationSenderName(null);
              offlineToastHelper("Verification cancelled");
            } else if (state === "emojis") {
              setVerificationStatus("emojis");
            } else if (state === "accepted") {
              setVerificationStatus("accepted");
            } else if (state === "sasStarted") {
              setVerificationStatus("sasStarted");
            }
          },
        );
        if (!cancelled) setVerificationStatus("idle");
      } catch (error) {
        if (!cancelled) console.error("Failed to set up verification:", error);
      }
    };

    setup();

    return () => {
      cancelled = true;
    };
  }, [client, syncService]);

  useEffect(() => {
    if (!client) return;

    let debounceTimer: ReturnType<typeof setTimeout> | null = null;

    // After user resets identity, we need to wait 2 seconds to ensure the verification state is updated
    const handle = VerificationService.subscribeToVerificationState((state) => {
      if (
        state === VerificationState.Unknown ||
        state === VerificationState.Verified
      ) {
        return;
      }

      if (debounceTimer) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
      }

      debounceTimer = setTimeout(() => {
        if (VerificationService.isDeviceVerified()) return;

        const currentRoute = NavigationContainerRef.getCurrentRoute();

        if (currentRoute && VERIFICATION_SCREENS.includes(currentRoute.name)) {
          return;
        }

        NavigationContainerRef.reset({
          index: 0,
          routes: [{ name: "confirmIdentity" }],
        });
      }, 2000);
    });

    return () => {
      if (debounceTimer) clearTimeout(debounceTimer);
      handle.cancel();
    };
  }, [client]);

  return <></>;
};

import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { VerificationService } from "modules/verification/service/VerificationService";
import { type FC, useEffect, useState } from "react";
import { Image } from "react-native";
import Toast from "react-native-toast-message";
import { Button, GoBackHeader, Loading, ScreenLayout } from "shared/components";
import { useNavigateToCorrectScreenHelper } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { EmojiVerification } from "../verify-user/fragments";

export const VerifyWithDevice: FC<
  NativeStackScreenProps<Routes, "verifyWithDevice">
> = ({ navigation }) => {
  const verificationStatus = useAtomValue(MatrixAtoms.verificationStatus);
  const [deviceId, setDeviceId] = useState<string | null>(null);
  const [requestSent, setRequestSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();

  const isWaiting =
    requestSent &&
    verificationStatus !== "emojis" &&
    verificationStatus !== "success" &&
    verificationStatus !== "failed" &&
    verificationStatus !== "cancelled";
  const isEmojis = verificationStatus === "emojis";

  useEffect(() => {
    setDeviceId(VerificationService.getDeviceId());
  }, []);

  // Initiate device verification on mount
  useEffect(() => {
    const requestVerification = async () => {
      try {
        await VerificationService.requestDeviceVerification();
        setRequestSent(true);
      } catch (err) {
        console.error("Failed to request device verification:", err);
        setError("Failed to send verification request. Please try again.");
      }
    };
    requestVerification();
  }, []);

  // When the other device accepts our request, start SAS to generate emojis
  useEffect(() => {
    if (verificationStatus === "accepted") {
      VerificationService.startVerification().catch((err) => {
        console.error("Failed to start SAS verification:", err);
        setError("Failed to start emoji verification. Please try again.");
        setRequestSent(false);
      });
    }
  }, [verificationStatus]);

  // Handle terminal states
  useEffect(() => {
    if (verificationStatus === "success") {
      Toast.show({
        text1: "Device verified successfully!",
        text2: "You can now access your encrypted messages",
        type: "success",
      });
      navigateToCorrectScreen();
    } else if (verificationStatus === "failed") {
      setError("Verification failed. Please try again.");
      setRequestSent(false);
    } else if (verificationStatus === "cancelled") {
      setError("Verification was cancelled. Please try again.");
      setRequestSent(false);
    }
  }, [verificationStatus]);

  const handleRetry = async () => {
    try {
      setError(null);
      setRequestSent(true);
      await VerificationService.requestDeviceVerification();
    } catch (err) {
      console.error("Failed to request device verification:", err);
      setError("Failed to send verification request. Please try again.");
    }
  };

  const handleCancel = async () => {
    try {
      await VerificationService.cancelVerification();
    } catch (err) {
      console.error("Failed to cancel verification:", err);
    }
    setRequestSent(false);
    setError("Verification was cancelled. Please try again.");
  };

  const handleGoBack = async () => {
    if (error) await handleCancel();
    navigation.goBack();
  };

  if (isEmojis) {
    return (
      <ScreenLayout>
        <GoBackHeader />
        <EmojiVerification />
      </ScreenLayout>
    );
  }

  return (
    <ScreenLayout>
      <GoBackHeader onGoBack={handleGoBack} />
      <Block flex={1} justify="space-between">
        <Block flex={1} justify="center" align="center" gap={32}>
          <Block gap={12}>
            <Text
              size={TextSize.large}
              textAlign="center"
              font="InstrumentSans-Medium"
            >
              Verify with another device
            </Text>
            <Text
              textAlign="center"
              font="InstrumentSans-Regular"
              color={Colors.white50}
            >
              A verification request has been sent to your other devices. Accept
              it on a verified device to compare emojis.
            </Text>
          </Block>

          {deviceId && (
            <Block
              border={{ borderRadius: 12 }}
              background={Colors.white5}
              paddings={[16, 16]}
              width="100%"
            >
              <Text color={Colors.white50} size={TextSize.small}>
                This device ID: {deviceId}
              </Text>
            </Block>
          )}

          {isWaiting && (
            <Block align="center" gap={16} width="100%">
              <Block flexDirection="row" align="center" gap={12}>
                <Block>
                  <Loading isFullScreen={false} width={20} height={20} />
                </Block>
                <Text color={Colors.white50}>
                  Waiting for the other device...
                </Text>
              </Block>
              <Block width="100%" paddings={[0, 52]}>
                <Button.Outline onPress={handleCancel}>Cancel</Button.Outline>
              </Block>
            </Block>
          )}

          {error && (
            <Block
              border={{ borderRadius: 12 }}
              background={Colors.white5}
              paddings={[16, 0]}
              gap={12}
              width="100%"
            >
              <Text color="red" textAlign="center">
                {error}
              </Text>
              <Block paddings={[0, 52]}>
                <Button.Primary onPress={handleRetry}>Try Again</Button.Primary>
              </Block>
            </Block>
          )}

          <Block
            border={{ borderRadius: 12 }}
            background={Colors.blackMinus3}
            paddings={[12, 16]}
            flexDirection="row"
            align="center"
            gap={12}
          >
            <Image
              source={require("assets/icons/info.png")}
              tintColor={Colors.primary}
              width={20}
              height={20}
            />
            <Text color={Colors.white80} size={TextSize.small} flex={1}>
              Don't have access to another verified device? Go back and use your
              recovery key instead.
            </Text>
          </Block>
        </Block>
      </Block>
    </ScreenLayout>
  );
};

