21	  const client = useAtomValue(MatrixAtoms.matrixClient);
22	  const syncService = useAtomValue(MatrixAtoms.syncService);
23	  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
24	  const setVerificationEmojis = useSetAtom(MatrixAtoms.verificationEmojis);
25	  const setVerificationSenderName = useSetAtom(
26	    MatrixAtoms.verificationSenderName,
27	  );
28	
29	  useEffect(() => {
30	    if (!client || !syncService) return;
31	
32	    let cancelled = false;
33	
34	    const setup = async () => {
35	      try {
36	        await VerificationService.setupVerification(
37	          // On verification request received
38	          (details) => {
39	            const senderName =
40	              details.senderProfile.displayName || details.senderProfile.userId;
41	            setVerificationSenderName(senderName);
42	            setVerificationStatus("incomingRequest");
43	            VerificationService.acknowledgeVerification(
44	              details.senderProfile.userId,
45	              details.flowId,
46	            ).catch((err) =>
47	              console.error("Failed to acknowledge verification:", err),
48	            );
49	            NavigationContainerRef.navigate("verifyUser", {
50	              userId: details.senderProfile.userId,
51	              flowId: details.flowId,
52	            });
53	          },
54	          // On emojis received
55	          (emojis) => {
56	            setVerificationEmojis(emojis);
57	            setVerificationStatus("emojis");
58	          },
59	          // On state change
60	          (state) => {
61	            console.log("Verification state changed:", state);
62	
63	            if (state === "success") {
64	              setVerificationStatus("success");
65	              setVerificationEmojis(null);
66	              setVerificationSenderName(null);
67	              Toast.show({
68	                type: "success",
69	                text1: "Device verified successfully!",
70	              });
71	            } else if (state === "failed") {
72	              setVerificationStatus("failed");
73	              setVerificationEmojis(null);
74	              setVerificationSenderName(null);
75	              offlineToastHelper("Verification failed");
76	            } else if (state === "cancelled") {
77	              setVerificationStatus("cancelled");
78	              setVerificationEmojis(null);
79	              setVerificationSenderName(null);
80	              offlineToastHelper("Verification cancelled");
81	            } else if (state === "emojis") {
82	              setVerificationStatus("emojis");
83	            } else if (state === "accepted") {
84	              setVerificationStatus("accepted");
85	            } else if (state === "sasStarted") {
86	              setVerificationStatus("sasStarted");
87	            }
88	          },
89	        );
90	        if (!cancelled) setVerificationStatus("idle");
91	      } catch (error) {
92	        if (!cancelled) console.error("Failed to set up verification:", error);
93	      }
94	    };
95	
96	    setup();
97	
98	    return () => {
99	      cancelled = true;
100	    };
101	  }, [client, syncService]);
102	
103	  useEffect(() => {
104	    if (!client) return;
105	
106	    let debounceTimer: ReturnType<typeof setTimeout> | null = null;
107	
108	    // After user resets identity, we need to wait 2 seconds to ensure the verification state is updated
109	    const handle = VerificationService.subscribeToVerificationState((state) => {
110	      if (
111	        state === VerificationState.Unknown ||
112	        state === VerificationState.Verified
113	      ) {
